def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"]:
        if marker in blob.lower():
            problems.append(f"  {name}: banned marker '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.180.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.179.0"' not in init:
        sys.exit("ABORT: not at v3.179.0.")
    for k in ("serial_batch", "counting"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("INV3", LESSONS_I3, QUESTIONS_I3, 9) + _validate("INV4", LESSONS_I4, QUESTIONS_I4, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("INV 3", LESSONS_I3, QUESTIONS_I3, "serial_batch",
         "Serial and batch operations in ZhiftERP: the two identities and what each buys; item configuration — Has Batch No, the manual manufacturer-number posture, expiry and shelf life, serial series and warranty — from the control register; the Batch record and the Serial and Batch Bundle mechanics with first-expiry-first-out; the Serial No record with dock capture and delivery verification; identity on every movement — mixed lots split honestly, transfers confirmed by identity, repack inheritance, per-batch counts; the expiry reads and lanes on their horizons; and the recall and freeze procedure with its time targets and the twice-yearly drill."),
        ("INV 4", LESSONS_I4, QUESTIONS_I4, "counting",
         "Stock reconciliation and counting in ZhiftERP: the Stock Reconciliation field walk — the two purposes, the set-to rule, the valuation-rate caution, the Difference Account, and what submission posts; count preparation with cut-off, the freeze setting, blind numbered sheets, and team separations; the floor rules including the double-count pass and the during-count procedure; entry, the recount pass, the threshold ladder, and the keeper review; the variance investigation — the document sweep first, the physical causes, the loss finding with the pattern file, and the upstream fix; and ABC cycle counting with the daily slice and the accuracy metric."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.179.0"', '"3.180.0"'))
    print("  data: INVENTORY 3 + 4 lessons + banks REPLACED (style v3, strict manual register)")
    print("wrote __version__ -> 3.180.0")


if __name__ == "__main__":
    main()
